clamp:
def main(x, lo, hi):
    if x < lo:
        return lo
    if x > hi:
        return hi
    return x

factorial:
def main(n):
    r = 1
    for i in range(2, n + 1):
        r *= i
    return r

fib:
def main(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

gcd:
def main(a, b):
    while b:
        a, b = b, a % b
    return a

collatz-steps:
def main(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps
